// src/lib/mcp/tools/list-weight-logs.ts
import { createClient as createClient4 } from "npm:@supabase/supabase-js@^2.98.0";
import { defineTool as defineTool4 } from "npm:@lovable.dev/mcp-js@0.20.0";
import { z } from "npm:zod@^4.4.3";
var list_weight_logs_default = defineTool4({
  name: "list_weight_logs",
  title: "Listar registros de peso",
  description: "Devuelve los \xFAltimos registros de peso corporal del usuario autenticado, m\xE1s recientes primero.",
  inputSchema: {
    limit: z.number().int().describe("N\xFAmero m\xE1ximo de registros a devolver (1-100).").optional()
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ limit }, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "No autenticado" }], isError: true };
    }
    const n = Math.min(Math.max(Number(limit ?? 30), 1), 100);
    const sb = createClient4(process.env.SUPABASE_URL, process.env.SUPABASE_PUBLISHABLE_KEY, {
      global: { headers: { Authorization: `Bearer ${ctx.getToken()}` } },
      auth: { persistSession: false, autoRefreshToken: false }
    });
    const { data, error } = await sb.from("weight_logs").select("*").eq("user_id", ctx.getUserId()).order("created_at", { ascending: false }).limit(n);
    if (error) return { content: [{ type: "text", text: error.message }], isError: true };
    return {
      content: [{ type: "text", text: JSON.stringify(data ?? []) }],
      structuredContent: { weight_logs: data ?? [] }
    };
  }
});

