import { createClient as createClient5 } from "npm:@supabase/supabase-js@^2.98.0";
import { defineTool as defineTool5 } from "npm:@lovable.dev/mcp-js@0.20.0";
import { z as z2 } from "npm:zod@^4.4.3";
var log_weight_default = defineTool5({
  name: "log_weight",
  title: "Registrar peso",
  description: "Guarda un nuevo registro de peso corporal (en kilogramos) para el usuario autenticado.",
  inputSchema: {
    weight_kg: z2.number().describe("Peso corporal en kilogramos (por ejemplo 78.5)."),
    note: z2.string().describe("Nota opcional sobre el registro.").optional()
  },
  annotations: { readOnlyHint: false, destructiveHint: false, idempotentHint: false, openWorldHint: false },
  handler: async ({ weight_kg, note }, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "No autenticado" }], isError: true };
    }
    if (!Number.isFinite(weight_kg) || weight_kg <= 20 || weight_kg > 400) {
      return { content: [{ type: "text", text: "Peso fuera de rango (20-400 kg)" }], isError: true };
    }
    const sb = createClient5(process.env.SUPABASE_URL, process.env.SUPABASE_PUBLISHABLE_KEY, {
      global: { headers: { Authorization: `Bearer ${ctx.getToken()}` } },
      auth: { persistSession: false, autoRefreshToken: false }
    });
    const { data, error } = await sb.from("weight_logs").insert({ user_id: ctx.getUserId(), weight_kg, note: note ?? null }).select().maybeSingle();
    if (error) return { content: [{ type: "text", text: error.message }], isError: true };
    return {
      content: [{ type: "text", text: `Peso registrado: ${weight_kg} kg` }],
      structuredContent: { weight_log: data }
    };
  }
});

